<?php require_once __DIR__.'/../../config/bootstrap.php'; require_internal(); require_first_access_clear(); $pdo=db(); $id=(int)($_GET['id']??0); $row=$id?$pdo->query("SELECT * FROM usuarios WHERE id=$id")->fetch():null; $pageTitle=$row?'Editar usuário':'Novo usuário';$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();$id=(int)($_POST['id']??0);$nome=trim($_POST['nome']??'');$login=trim($_POST['login']??'');$email=trim($_POST['email']??'');$senha=$_POST['senha']??'';if($nome===''||$login==='')$error='Nome e login são obrigatórios.';else{try{$now=now();if($id){if($senha!==''){$st=$pdo->prepare('UPDATE usuarios SET nome=?,login=?,email=?,senha_hash=?,primeiro_acesso=0,atualizado_em=? WHERE id=?');$st->execute([$nome,$login,$email,password_hash($senha,PASSWORD_DEFAULT),$now,$id]);}else{$st=$pdo->prepare('UPDATE usuarios SET nome=?,login=?,email=?,atualizado_em=? WHERE id=?');$st->execute([$nome,$login,$email,$now,$id]);}log_action('alteração de usuário','usuarios',$id);flash('success','Usuário atualizado com sucesso.');}else{$st=$pdo->prepare('INSERT INTO usuarios(nome,login,email,senha_hash,tipo,ativo,primeiro_acesso,criado_em,atualizado_em) VALUES(?,?,?,?,?,?,?,?,?)');$st->execute([$nome,$login,$email,password_hash($senha?:'admin123',PASSWORD_DEFAULT),'interno',1,$senha===''?1:0,$now,$now]);$id=(int)$pdo->lastInsertId();log_action('criação de usuário','usuarios',$id);flash('success','Usuário criado com sucesso.');}redirect('index.php');}catch(Throwable $e){$error='Não foi possível salvar. Verifique se o login já existe.';}}}
include __DIR__.'/../../includes/header.php'; ?><div class="page-head"><div><h1><?=e($pageTitle)?></h1></div><a class="btn secondary" href="index.php">Voltar</a></div><div class="card"><?php if($error): ?><div class="alert danger"><?=e($error)?></div><?php endif; ?><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="id" value="<?=$id?>"><div class="form-grid"><div class="field col-6"><label>Nome</label><input name="nome" required value="<?=e($row['nome']??'')?>"></div><div class="field col-6"><label>Login</label><input name="login" required value="<?=e($row['login']??'')?>"></div><div class="field col-6"><label>E-mail</label><input type="email" name="email" value="<?=e($row['email']??'')?>"></div><div class="field col-6"><label>Senha <?= $row?'(deixe em branco para manter)':''?></label><input type="password" name="senha" <?=$row?'':'required'?>></div></div><div class="form-actions"><button class="btn primary">Salvar</button></div></form></div><?php include __DIR__.'/../../includes/footer.php'; ?>
